Hi @nabenabe0928 no, I didn't investigate much `BruteForceSampler` as I tried to make it work with `GridSampler` instead. My mistake. What I did was actually building a custom validation method where I can add constraints manually. Nevertheless, this was the "alternative" solution: would it be possible to generate constraints dynamically: evaluate the search space and exclude incompatible combination without the user defined constraints?

## My workaround:

```python
import numpy as np
import optuna
from sklearn.model_selection import cross_val_score
from sklearn.utils import check_X_y
import torch
from itertools import product

def validate_string(string):
    if isinstance(string, str) and '_' in string:
        q1, q2 = string.split('_')
        try:
            q1, q2 = int(q1), int(q2)
        except ValueError:
            try:
                q1, q2 = float(q1), float(q2)
            except ValueError:
                return string
        if q1 < 0 or q2 > 100 or q1 >= q2:
            raise ValueError(f"Invalid quantile range: {string}. Must be in the format 'x_y' where 0 <= x < y <= 100.")
        return (q1, q2)
    return string

class Constraints:
    OPERATORS = {
        '==': lambda x, y: x == y,
        '!=': lambda x, y: x != y,
        '>=': lambda x, y: x >= y,
        '<=': lambda x, y: x <= y,
        '>': lambda x, y: x > y,
        '<': lambda x, y: x < y,
    }

    def __init__(self, rules):
        self.rules = rules

    def _parse_condition(self, cond):
        if '__' in cond and '=' in cond:
            key, val = cond.split('=')
            val = val.strip("\"'")
            val = validate_string(val)
            if isinstance(val, str):
                if val.lower() == 'none':
                    val = None
                elif val.lower() == 'true':
                    val = True
                elif val.lower() == 'false':
                    val = False
            return key, val
        return cond, None

    def is_valid(self, params):
        for rule in self.rules:
            left, op, right = rule
            left_key, left_val = self._parse_condition(left)

            if left_val is not None:
                if params.get(left_key) != left_val:
                    continue
                right_val = params.get(op)
                if right_val not in right:
                    return False
            else:
                left_val = params.get(left)
                right_val = params.get(right) if isinstance(right, str) else right
                if left_val is None or right_val is None:
                    continue
                if not self.OPERATORS[op](left_val, right_val):
                    return False
        return True

class DynamicSearchObjective:
    def __init__(self, pipeline, steps, X_train, y_train, validate_search_space=False, scoring='roc_auc'):
        self.pipeline = pipeline
        self.steps = steps
        self.X_train, self.y_train = check_X_y(X_train, y_train, accept_sparse=True)
        self.n_features = self.X_train.shape[1]
        self.min_class_count = np.bincount(self.y_train)[np.bincount(self.y_train) > 0].min()
        self.scoring = scoring
        self.search_space = self._get_search_space()
        self.validate_search_space = validate_search_space
        self.valid_combos = None
        self.n_trials = None
        self.trial_number = 0
        if self.validate_search_space:
            self.valid_combos = self._validate_search_space()
            self.n_trials = len(self.valid_combos)
        # self.device = 'cuda' if torch.cuda.is_available() else 'cpu'

    def _get_search_space(self):
        search_space = {}
        for step_name, step_obj in self.steps:
            cname = step_obj.__class__.__name__.lower()
            if cname == 'robustscaler':
                search_space[f'{step_name}__quantile_range'] = ['10_90', '25_75']
            elif cname == 'powertransformer':
                search_space[f'{step_name}__standardize'] = [True]
            elif cname == 'smote':
                search_space[f'{step_name}__k_neighbors'] = list(range(1, min(self.min_class_count - 1, 3)))
                search_space[f'{step_name}__sampling_strategy'] = ['auto', 'minority']
            elif cname == 'adasyn':
                search_space[f'{step_name}__n_neighbors'] = list(range(1, min(self.min_class_count - 1, 3)))
                search_space[f'{step_name}__sampling_strategy'] = ['auto', 'minority']
            elif cname == 'pca':
                search_space[f'{step_name}__n_components'] = [3, 5, 15]
                search_space[f'{step_name}__whiten'] = [False]
                search_space[f'{step_name}__svd_solver'] = ['auto', 'full', 'arpack', 'randomized']
            elif cname == 'selectkbest':
                search_space[f'{step_name}__k'] = [3, 5, 15]
            elif cname == 'sequentialfeatureselector':
                search_space[f'{step_name}__direction'] = ['forward', 'backward']
            elif cname == 'rfe':
                search_space[f'{step_name}__n_features_to_select'] = [3, 5, 15]
            elif cname == 'logisticregression':
                search_space[f'{step_name}__C'] = [float(x) for x in np.logspace(-3, 0, num=3)]
                search_space[f'{step_name}__penalty'] = ['l1', 'l2']
                search_space[f'{step_name}__solver'] = ['liblinear', 'saga', 'lbfgs']
                search_space[f'{step_name}__class_weight'] = [None, 'balanced']
            elif cname == 'xgbclassifier':
                search_space[f'{step_name}__n_estimators'] = list(range(100, 501, 100))
                search_space[f'{step_name}__learning_rate'] = [float(x) for x in np.logspace(-3, 0, num=4)]
                search_space[f'{step_name}__max_depth'] = [int(x) for x in np.linspace(3, 10, num=4).astype(int)]
                search_space[f'{step_name}__subsample'] = [float(x) for x in np.linspace(0.5, 1.0, num=3)]
                search_space[f'{step_name}__colsample_bytree'] = [float(x) for x in np.linspace(0.5, 1.0, num=3)]
            elif cname == 'randomforestclassifier':
                search_space[f'{step_name}__n_estimators'] = list(range(100, 501, 100))
                search_space[f'{step_name}__max_depth'] = [int(x) for x in np.linspace(3, 10, num=4).astype(int)]
                search_space[f'{step_name}__min_samples_split'] = [int(x) for x in np.linspace(3, 10, num=4).astype(int)]
                search_space[f'{step_name}__min_samples_leaf'] = [int(x) for x in np.linspace(1, 5, num=3).astype(int)]
            elif cname == 'xgbregressor' or cname == 'randomforestregressor':
                search_space[f'{step_name}__n_estimators'] = list(range(100, 501, 100))
            elif cname == 'ridge':
                search_space[f'{step_name}__alpha'] = [float(x) for x in np.logspace(-3, 2, num=4)]
            elif cname == 'lasso':
                search_space[f'{step_name}__alpha'] = [float(x) for x in np.logspace(-4, 0, num=10)]
            elif cname == 'elasticnet':
                search_space[f'{step_name}__alpha'] = [float(x) for x in np.logspace(-4, 0, num=10)]
                search_space[f'{step_name}__l1_ratio'] = [float(x) for x in np.linspace(0.1, 0.9, num=5)]

        for k, values in search_space.items():
            search_space[k] = [validate_string(v) if isinstance(v, str) else v for v in values]

        return search_space

    def _validate_search_space(self):
        constraints = Constraints([
            ('pca__n_components', '>=', 'selectkbest__k'),
            ('logisticregression__penalty=l1', 'logisticregression__solver', ['saga', 'liblinear']),
            ('logisticregression__solver=lbfgs', 'logisticregression__penalty', ['l2']),
        ])
        all_combinations = [
            {
                k: validate_string(v) if isinstance(v, str) else v
                for k, v in zip(self.search_space.keys(), values)
            }
            for values in product(*self.search_space.values())
        ]
        valid_combinations = [combo for combo in all_combinations if constraints.is_valid(combo)]
        min_samples_features = min(self.X_train.shape[0], self.X_train.shape[1])
        filtered_combos = []
        for combo in valid_combinations:
            if (
                combo.get('pca__svd_solver') == 'arpack'
                and 'pca__n_components' in combo
                and combo['pca__n_components'] >= min_samples_features
            ):
                continue
            if (
                combo.get('logisticregression__solver') == 'liblinear'
                and combo.get('logisticregression__penalty') == 'l1'
            ):
                continue
            filtered_combos.append(combo)
        return filtered_combos


    def _get_trial_results(self, params):
        try:
            self.pipeline.set_params(**params)
            score = cross_val_score(self.pipeline, self.X_train, self.y_train, cv=5, scoring=self.scoring, error_score='raise').mean()
            return score
        except Exception as e:
            print(f"Pipeline failed with params: {params}, error: {e}")
            return float('nan')

    def __call__(self, trial: optuna.trial.Trial):
        if not self.validate_search_space:
            params = {}
            for step_name, _ in self.steps:
                for param_name, values in self.search_space.items():
                    if not param_name.startswith(f"{step_name}__"):
                        continue

                    if isinstance(values[0], (str, type(None), bool)):
                        value = trial.suggest_categorical(param_name, values)
                        value = validate_string(value)
                    elif isinstance(values[0], int):
                        value = trial.suggest_int(param_name, min(values), max(values))
                    elif isinstance(values[0], float):
                        value = trial.suggest_float(param_name, min(values), max(values))
                    else:
                        raise ValueError(f"Unsupported type in search space: {type(values[0])}")

                    params[param_name] = value
            # params = self._set_device(params)
            for param_name, value in params.items():
                trial.set_user_attr(param_name, value)
            return self._get_trial_results(params)
        else:
            combo = self.valid_combos[self.trial_number]
            # combo = self._set_device(combo)
            for param_name, value in combo.items():
                trial.set_user_attr(param_name, value)
            self.trial_number += 1
            return self._get_trial_results(combo)
```

With this constraints a slight reduction of the search space I was able to reduce the number of trials to ~4600 for `LogisticRegression` (with PCA, SMOTE, etc.), 720 for `XGBoost` and 240 for `RandomForest`. Some trials still fail but it takes a lot less to run.

